import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// n lines of `price` each, qty 1
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// issue #12: the customer discount is applied exactly once
test('customer discount 0.1 on a 1,000 cart under 10 lines is 900', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

// 10,000 -> 9,000 after the customer discount -> 8,550 after the 5% bulk discount
test('10 lines: 5% bulk discount applies once, after the customer discount', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

// 9 lines is below the bulk threshold: 9,000 -> 8,100, customer discount only
test('9 lines: customer discount only, no bulk discount', () => {
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

// Discount rate 0 must stay as it was before the issue #12 fix.
test('discount rate 0, 10 lines: only the 5% bulk discount applies', () => {
  assert.equal(total(lines(10, 1000), 0), 9500);
});

// 3,330 * 0.95 = 3,163.5, rounded to 3,164
test('discount rate 0, 10 lines: total is rounded to the nearest unit', () => {
  assert.equal(total(lines(10, 333), 0), 3164);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
